const a=e=>e.sol.ok?Math.max(0,...e.sol.members.filter(t=>t.id.startsWith("C")).map(t=>Math.max(Math.abs(t.maxM.value),Math.abs(t.minM.value)))):0,n=e=>e.sol.ok?Math.max(0,...e.sol.members.filter(t=>t.id.startsWith("G")).map(t=>t.maxM.value)):0,s=e=>e.sol.ok?Math.max(0,...e.sol.members.map(t=>-t.minM.value)):0,r=[{id:"l.rc-sys-girders.slender",xp:30,title:{en:"Slim the columns until they take less than 10% of the girder's simple-span moment",ar:"نحّف الأعمدة لحد ما تاخد أقل من 10% من عزم الكمرة البسيطة"},check:e=>e.template==="girder"&&e.params.sys==="simple"&&e.params.joint==="rigid"&&a(e)>0&&a(e)<.1*n(e)+1e-9&&a(e)<72.5},{id:"l.rc-sys-girders.frame",xp:30,title:{en:"Deepen the columns to t_c ≥ 0.8·t_G: the joint is rigid and the girder becomes a frame beam",ar:"عمّق الأعمدة لحد t_c ≥ 0.8·t_G: العقدة جاسئة والكمرة بقت كمرة إطار"},check:e=>e.template==="girder"&&e.params.joint==="rigid"&&Number(e.params.r)>=.8&&e.tab==="hand"},{id:"l.rc-sys-girders.real",xp:20,title:{en:"Give the girder a real hinge on its columns and compare the span moment with wL²/8",ar:"ادّي الكمرة مفصلة حقيقية على أعمدتها وقارن عزم البحر بـ wL²/8"},check:e=>e.template==="girder"&&e.params.joint==="hinged"&&e.sol.ok}],i=[{id:"l.rc-sys-girders.hc",xp:40,title:{en:"Balance the two-span girder until its support moment is within 1% of wL²/8",ar:"وازن الكمرة ذات البحرين لحد ما عزم ركيزتها يبقى في حدود 1% من wL²/8"},check:e=>e.preset==="two"&&e.releases>0&&e.error<.01}],o=[{id:"l.rc-sys-girders.cant",xp:30,title:{en:"Add cantilevers at both ends and watch the span moment fall",ar:"ضيف كوابيل عند الطرفين وشوف عزم البحر وهو بينزل"},check:e=>e.template==="girder"&&e.params.sys==="cant"&&e.params.joint==="hinged"&&e.sol.ok},{id:"l.rc-sys-girders.gerber",xp:40,title:{en:"Make the two-span girder determinate with a hinge at L/5 (on real column hinges)",ar:"خلّي الكمرة ذات البحرين محددة بمفصلة عند L/5 (على مفصلات أعمدة حقيقية)"},check:e=>e.template==="girder"&&e.params.sys==="gerber"&&e.params.joint==="hinged"&&e.sol.ok&&e.sol.degree.doi<=2}],m=[{id:"l.rc-sys-girders.haunch",xp:30,title:{en:"Haunch the two-span girder over its middle support and read how much moment the haunch attracts",ar:"اعمل فيونكة للكمرة ذات البحرين فوق ركيزتها الوسطية واقرا الفيونكة جذبت عزم قد إيه"},check:e=>e.template==="haunch"&&e.params.sys==="cont"&&e.params.shape==="haunched"&&e.tab==="hand"},{id:"l.rc-sys-girders.compare",xp:20,title:{en:"Switch the fixed-ended span between uniform and haunched",ar:"بدّل البحر ثابت الطرفين بين منتظم وبفيونكات"},check:e=>e.template==="haunch"&&e.params.sys==="fixed"&&e.params.shape==="uniform"&&s(e)>0}],d={sections:[{id:"joint",title:{en:"Girder or frame? The joint decides",ar:"كمرة ولا إطار؟ العقدة هي اللي بتقرر"},blocks:[{t:"p",text:{en:"A beam cast on columns shares its end moment with them in proportion to their stiffness. The ratio $K_r = K_b/K_c$ tells which one wins: a stiff beam on flexible columns turns freely at its ends — the joint acts as a hinge and the beam is a **girder**; stiff columns hold its ends — the joint is rigid and the beam belongs to a **frame**. In practice the depths decide:",ar:"الكمرة المصبوبة على أعمدة بتقسم عزم طرفها معاهم بنسبة جساءتهم. النسبة $K_r = K_b/K_c$ بتقول مين اللي بيكسب: كمرة جاسئة على أعمدة مرنة بتلف بحرية عند أطرافها — العقدة بتشتغل مفصلة والكمرة **Girder**؛ وأعمدة جاسئة بتمسك أطرافها — العقدة جاسئة والكمرة جزء من **إطار**. وفي الشغل الأعماق هي اللي بتقرر:"}},{t:"eq",tex:["K_b = \\dfrac{EI_b}{L},\\quad K_c = \\dfrac{EI_c}{H},\\quad K_r = \\dfrac{K_b}{K_c} = \\dfrac{t_b^3/L}{t_c^3/H}","t_c \\le \\dfrac{t_b}{2}","t_c \\ge 0.8\\,t_b"],caption:{en:"Second line: the joint acts as a hinge; third line: the joint is rigid (same width b and E).",ar:"السطر التاني: العقدة بتشتغل مفصلة؛ والسطر التالت: العقدة جاسئة (نفس العرض b و E)."}},{t:"p",text:{en:"A girder on columns no deeper than itself ($t_c \\le t_G$) is designed as simply supported for its span moment, and its columns — and the top steel over them — for the small moment $wL^2/24$ that still gets through. **Example:** a 10 m girder 300 × 1000 on 5 m columns with 10 kN/m of own weight and three secondary beams of 120 kN inside its span (every 2.5 m), smeared over the span as shown further on: $w = 10 + 3\\times120/10 = 46$ kN/m, $wL^2/8 = 575$ kN·m and $wL^2/24 = 191.7$ kN·m. With 450 mm columns $K_r = (1.0^3/10)/(0.45^3/5) = 5.49$ → hinge; with 850 mm columns $K_r = 0.81$ → rigid. The lab carries the three beams as real point loads — 725 kN·m on real hinges — and even 500 mm columns cast with the girder take 152.4 kN·m and cut its span moment to 572.6, inside the 191.7 kN·m the rule gives them; with 300 mm columns only 44.6 kN·m.",ar:"الكمرة اللي على أعمدة مش أعمق منها ($t_c \\le t_G$) بتتصمم بسيطة الارتكاز على عزم بحرها، وأعمدتها — والحديد العلوي فوقهم — على العزم الصغير $wL^2/24$ اللي لسه بيعدّي. **مثال:** كمرة 10 م مقاس 300 × 1000 على أعمدة 5 م، ووزنها الذاتي 10 kN/m وجوه بحرها تلات كمرات متشالة 120 kN (كل 2.5 م)، مفروشين على البحر زي ما هييجي بعدين: $w = 10 + 3\\times120/10 = 46$ kN/m، و $wL^2/8 = 575$ kN·m، و $wL^2/24 = 191.7$ kN·m. بأعمدة 450 مم $K_r = (1.0^3/10)/(0.45^3/5) = 5.49$ ← مفصلة؛ وبأعمدة 850 مم $K_r = 0.81$ ← جاسئة. والمعمل بيحط التلات كمرات أحمال مركزة حقيقية — 725 kN·m على مفصلات حقيقية — وحتى أعمدة 500 مم مصبوبة مع الكمرة بتاخد 152.4 kN·m وبتنزّل عزم البحر لـ 572.6، جوه الـ 191.7 kN·m اللي القاعدة بتديهولهم؛ وبأعمدة 300 مم 44.6 kN·m بس."}},{t:"p",text:{en:"**A gable tied at its eaves is a girder too.** A tie between the two knees takes the whole thrust, so the columns receive none of it: the roof sits on its columns like a girder and is solved on its own — a hinge and a roller, the tie force as the redundant, by virtual work (the polygon-frame and saw-tooth episodes). The tie stretches a little and the knee is no perfect hinge, so small moments still reach the column heads: they call for **no footing shift**, but the girder's top bars are continued down into the columns so that the joint does not crack. A **hanger** from the ridge to the middle of the tie keeps the long tie from sagging. The tie bars run its full length and loop round the eaves joints; the hanger bars are hooked round the tie. The tie itself is a slim member, about 300 mm deep, and the columns, which receive almost no moment, stay prismatic. A tie placed lower, between the footings, leaves a two-hinged frame instead — one whose footings simply need no shift: the tie runs along the ground between the footings on small pads and takes the thrust $X$, and the frame is solved as a two-hinged gable, by virtual work or by the approximate method.",ar:"**الإطار الجمالوني اللي عليه شداد عند الركنين برضه كمرة (Girder).** الشداد بين الركنين بياخد الدفع كله، فالأعمدة مابتاخدش منه حاجة: السقف راكب على أعمدته زي الكمرة وبيتحل لوحده — مفصلة وركيزة متحركة، وقوة الشداد هي المجهول الزائد، بالشغل الافتراضي (حلقتي الإطار المضلع والسقف المنشاري). والشداد بيستطيل شوية والركن مش مفصلة مثالية، فعزوم صغيرة لسه بتوصل لرؤوس الأعمدة: مش محتاجة **ترحيل قواعد**، بس الحديد العلوي للكمرة بيكمّل لتحت جوه الأعمدة علشان الوصلة ماتتشرخش. و**معلّق** من خط القمة لنص الشداد بيمنع الشداد الطويل إنه يترخّم. وحديد الشداد بيمشي بطوله كله وبيلف حوالين وصلتين الركن؛ وحديد المعلّق بيخلص بجنش حوالين الشداد. والشداد نفسه عضو نحيف، عمقه حوالي 300 مم، والأعمدة، اللي تقريباً مابتاخدش عزم، بتفضل منتظمة القطاع. ولو الشداد اتحط أوطى، بين القواعد، بيبقى إطار ذو مفصلين بدل كده — قواعده بس مش محتاجة ترحيل: الشداد بيمشي على الأرض بين القواعد على مخدات صغيرة وبياخد الدفع $X$، والإطار بيتحل كجمالون ذو مفصلين، بالشغل الافتراضي أو بالطريقة التقريبية."}},{t:"p",text:{en:"**Example.** A gable 18 m wide with a 3.6 m rise, tied at its eaves, carries $w = 28$ kN/m on plan. Cut the tie and apply the unit pair: $M_1 = y$ on the rafters and zero on the columns, so both integrals run over the rafters only and give $X = \\int M_0\\,y\\,ds/\\int y^2\\,ds = 5wL^2/(32f) = 5\\times28\\times18^2/(32\\times3.6) = 393.75$ kN — a quarter more than $M_0/f = 315$ kN, because a load spread along the rafters is not the funicular of a triangle, so the rafters bend. The apex then hogs, $wL^2/8 - X f = -wL^2/32 = -283.5$ kN·m: each rafter works like a beam of $L/2 = 9$ m pinned at the eaves and held at the apex, its largest sagging moment $9w(L/2)^2/128 = 159.5$ kN·m at 3.375 m from the eaves (on plan). The columns carry only $wL/2 = 252$ kN, and the tie needs $393.75\\times10^3/347.8 = 1132$ mm² → 4Ø20 ($f_y = 400$).",ar:"**مثال.** جمالون عرضه 18 م وارتفاعه 3.6 م، عليه شداد عند الركنين، وشايل $w = 28$ kN/m على المسقط الأفقي. اقطع الشداد وحط زوج قوى الوحدة: $M_1 = y$ على الـ Rafters وصفر على الأعمدة، فالتكاملين على الـ Rafters بس وبيدّوا $X = \\int M_0\\,y\\,ds/\\int y^2\\,ds = 5wL^2/(32f) = 5\\times28\\times18^2/(32\\times3.6) = 393.75$ kN — ربع أكتر من $M_0/f = 315$ kN، لأن الحمل الموزع على الـ Rafters مش هو الشكل الحبلي للمثلث، فالـ Rafters بتنحني. وساعتها القمة عليها عزم سالب، $wL^2/8 - X f = -wL^2/32 = -283.5$ kN·m: كل Rafter بيشتغل زي كمرة $L/2 = 9$ م مفصلية عند الركن ومتثبتة عند القمة، وأكبر عزم موجب فيها $9w(L/2)^2/128 = 159.5$ kN·m على بعد 3.375 م من الركن (على المسقط الأفقي). والأعمدة شايلة $wL/2 = 252$ kN بس، والشداد محتاج $393.75\\times10^3/347.8 = 1132$ مم² ← 4Ø20 ($f_y = 400$)."}},{t:"lab",lab:"frame",height:470,props:{template:"girder",lockTemplate:!0,missions:r},caption:{en:"A 10 m girder on two columns: change t_c/t_G and the joint; the Hand method tab gives K_r and the girder rules.",ar:"كمرة 10 م على عمودين: غيّر t_c/t_G والوصلة؛ وتبويب الحل اليدوي بيدّي K_r وقواعد الكمرات."}},{t:"quiz",q:{kind:"num",q:{en:"Girder 800 mm deep on 8 m, columns 400 mm deep and 4 m high. K_r?",ar:"كمرة عمقها 800 مم على 8 م، وأعمدة عمقها 400 مم وارتفاعها 4 م. K_r؟"},answer:4,tol:.003,explain:{en:"$(0.8^3/8)/(0.4^3/4) = 0.064/0.016 = 4$ — and $t_c = t_b/2$: a hinge.",ar:"$(0.8^3/8)/(0.4^3/4) = 0.064/0.016 = 4$ — و $t_c = t_b/2$: مفصلة."}}}]},{id:"stiffness",title:{en:"Stiffness shapes the diagram: the two-hinged frame",ar:"الجساءة بتشكّل منحنى العزوم: الإطار ذو المفصلين"},blocks:[{t:"p",text:{en:"The same idea holds for a whole **two-hinged frame** under a uniform load $w$ on its beam: the free moment $wL^2/8$ is shared between the knees ($M_1$) and mid-span ($M_2$) according to the stiffness of the beam against the columns. Three cases are enough to sketch the B.M.D:",ar:"نفس الفكرة بتنطبق على **إطار ذو مفصلين** كامل تحت حمل موزع منتظم $w$ على كمرته: العزم الحر $wL^2/8$ بيتقسم بين الأركان ($M_1$) ونص البحر ($M_2$) حسب جساءة الكمرة قصاد الأعمدة. وتلات حالات كفاية ترسم بيهم منحنى العزوم:"}},{t:"table",head:[{en:"Stiffness",ar:"الجساءة"},{en:"Knee M₁",ar:"الركن M₁"},{en:"Mid-span M₂",ar:"نص البحر M₂"},{en:"The beam works like",ar:"الكمرة بتشتغل زي"}],rows:[[{en:"$I_b \\gg I_c$ — deep beam, slender columns",ar:"$I_b \\gg I_c$ — كمرة عميقة وأعمدة نحيفة"},"$\\approx 0$","$\\approx wL^2/8$",{en:"a simple beam — a girder",ar:"كمرة بسيطة — Girder"}],[{en:"$I_b \\approx I_c$",ar:"$I_b \\approx I_c$"},"$\\approx wL^2/16$","$\\approx wL^2/16$",{en:"between the two",ar:"بين الاتنين"}],[{en:"$I_b \\ll I_c$ — very stiff columns",ar:"$I_b \\ll I_c$ — أعمدة جاسئة جداً"},"$\\approx wL^2/12$","$\\approx wL^2/24$",{en:"a fixed-ended beam",ar:"كمرة ثابتة الطرفين"}]]},{t:"eq",tex:["M_1 = \\dfrac{wL^2}{4\\,(2k + 3)},\\qquad k = \\dfrac{I_b}{I_c}\\,\\dfrac{h}{L},\\qquad M_2 = \\dfrac{wL^2}{8} - M_1","M_1 = \\dfrac{3FL}{8\\,(2k + 3)},\\qquad M_2 = \\dfrac{FL}{4} - M_1"],caption:{en:"The exact knee moment of a symmetric two-hinged frame under a uniform load w on the beam (first line) or a point load F at mid-span (second line). k → ∞ gives the simple beam; k → 0 the fixed-ended beam (wL²/12 and wL²/24, or FL/8 at the knees and at mid-span); M₁ = M₂ = wL²/16 exactly at k = 0.5.",ar:"العزم المضبوط عند ركن إطار ذو مفصلين متماثل تحت حمل موزع منتظم w على الكمرة (السطر الأول) أو حمل مركز F في النص (السطر التاني). k ← ∞ بتدّي الكمرة البسيطة؛ و k ← 0 الكمرة ثابتة الطرفين (wL²/12 و wL²/24، أو FL/8 عند الأركان وفي النص)؛ و M₁ = M₂ = wL²/16 بالظبط عند k = 0.5."}},{t:"p",text:{en:"**Determinate frames are different.** On a hinge and a roller (or with three hinges) the moments come from statics alone: **the stiffness of the members changes neither the value nor the shape of the B.M.D.** A hinge-and-roller frame under a mid-span load gives the simple-beam triangle $FL/4$ whatever its depths. **Example.** A frame 12 m wide and 6 m high, $w = 40$ kN/m ($wL^2/8 = 720$ kN·m). Beam and columns of equal $I$ ($k = 0.5$): $M_1 = M_2 = 360$ kN·m $= wL^2/16$. Columns twenty times stiffer ($k = 0.025$): $M_1 = 472.1$ and $M_2 = 247.9$ kN·m — close to $wL^2/12 = 480$ and $wL^2/24 = 240$. Beam twenty times stiffer ($k = 10$): $M_1 = 62.6$ and $M_2 = 657.4$ kN·m — nearly a girder. On a hinge and a roller: 0 and 720 kN·m, whatever the depths. A load of 200 kN at mid-span with $k = 0.5$: 225 kN·m at the knees and 375 at mid-span (out of $FL/4 = 600$).",ar:"**الإطارات المحددة حاجة تانية.** على مفصلة وركيزة متحركة (أو بتلات مفصلات) العزوم بتطلع من الاتزان لوحده: **جساءة الأعضاء مابتغيّرش لا قيمة منحنى العزوم ولا شكله.** إطار على مفصلة وركيزة متحركة تحت حمل في النص بيدّي مثلث الكمرة البسيطة $FL/4$ مهما كانت أعماقه. **مثال.** إطار عرضه 12 م وارتفاعه 6 م، و $w = 40$ kN/m ($wL^2/8 = 720$ kN·m). كمرة وأعمدة بنفس الـ $I$ ($k = 0.5$): $M_1 = M_2 = 360$ kN·m $= wL^2/16$. أعمدة أجسأ عشرين مرة ($k = 0.025$): $M_1 = 472.1$ و $M_2 = 247.9$ kN·m — قريب من $wL^2/12 = 480$ و $wL^2/24 = 240$. وكمرة أجسأ عشرين مرة ($k = 10$): $M_1 = 62.6$ و $M_2 = 657.4$ kN·m — تقريباً Girder. وعلى مفصلة وركيزة متحركة: 0 و 720 kN·m، مهما كانت الأعماق. وحمل 200 kN في النص مع $k = 0.5$: 225 kN·m عند الأركان و 375 في النص (من $FL/4 = 600$)."}},{t:"quiz",q:{kind:"num",q:{en:"Two-hinged frame L = 10 m, h = 5 m, beam and columns of equal I, w = 48 kN/m. Knee moment (kN·m)?",ar:"إطار ذو مفصلين L = 10 م و h = 5 م، والكمرة والأعمدة بنفس الـ I، و w = 48 kN/m. عزم الركن (kN·m)؟"},answer:300,tol:.003,unit:"kN·m",explain:{en:"$k = 1\\times5/10 = 0.5$ → $M_1 = M_2 = wL^2/16 = 48\\times100/16 = 300$ kN·m.",ar:"$k = 1\\times5/10 = 0.5$ ← $M_1 = M_2 = wL^2/16 = 48\\times100/16 = 300$ kN·m."}}}]},{id:"types",title:{en:"Girder types, spans and depths",ar:"أنواع الكمرات وبحورها وأعماقها"},blocks:[{t:"table",head:[{en:"Girder",ar:"الكمرة"},{en:"Span",ar:"البحر"},{en:"Depth t_G",ar:"العمق t_G"},{en:"Soil",ar:"التربة"}],rows:[[{en:"simple",ar:"بسيطة"},"4–12 m","$L/10$",{en:"any",ar:"أي تربة"}],[{en:"continuous",ar:"مستمرة"},"4–12 m","$L/12$",{en:"medium or hard",ar:"متوسطة أو قوية"}],[{en:"cantilever",ar:"كابولي"},"—","$L_c/5$","—"]],caption:{en:"Columns t_c ≈ 0.7–0.9 t_G (never deeper than the girder); width b = max(0.30 m, spacing/20).",ar:"الأعمدة t_c ≈ 0.7–0.9 t_G (وأبداً مش أعمق من الكمرة)؛ والعرض b = max(0.30 م، المسافة/20)."}},{t:"p",text:{en:'Beyond about 12 m a girder on ordinary columns is no longer "a beam on pins": the columns needed to carry it are deep enough to fix it, and it works as a frame — unless it sits on **real supports** (neoprene bearings), which cut the frame action on purpose. So over 12 m the system is chosen as a **frame** instead, and a **two-hinged** frame is preferred to a fixed one where the soil allows: it is far easier to solve by hand. Where columns may stand inside the hall, a sloping roof can also be carried by **inclined girders** that follow its slope from column to column, $L/10$ deep on their plan span — two 10 m bays rising to a middle column take two 1.0 m girders, with the roof slab spanning between neighbouring girders.',ar:"بعد حوالي 12 م الكمرة على أعمدة عادية مابقتش «كمرة على مفصلات»: الأعمدة اللي بتشيلها بتبقى عميقة كفاية إنها تثبّتها، فبتشتغل إطار — إلا لو راكبة على **ركائز حقيقية** (ركائز نيوبرين)، اللي بتقطع عمل الإطار عمداً. علشان كده بعد 12 م بنختار **إطار** بدل الكمرة، ويُفضَّل **الإطار ذو المفصلين** عن الثابت لو التربة تسمح: حله باليد أسهل بكتير. ولما يبقى مسموح بأعمدة جوه الصالة، السقف المايل ممكن كمان يتشال على **كمرات مايلة** ماشية مع ميله من عمود لعمود، عمقها $L/10$ على بحرها في المسقط الأفقي — بايكتين 10 م طالعين لعمود في النص بياخدوا كمرتين 1.0 م، وبلاطة السقف بحرها بين الكمرات اللي جنب بعض."}},{t:"quiz",q:{kind:"num",q:{en:"A continuous girder spanning 9 m. Its depth by the rule (m)?",ar:"كمرة مستمرة بحرها 9 م. عمقها بالقاعدة (م)؟"},answer:.75,tol:.003,unit:"m",explain:{en:"$L/12 = 9/12 = 0.75$ m.",ar:"$L/12 = 9/12 = 0.75$ م."}}}]},{id:"secondary",title:{en:"Secondary beams and the loads on a girder",ar:"الكمرات المتشالة والأحمال على الكمرة"},blocks:[{t:"p",text:{en:"Girders are spaced $S$ apart; **secondary beams** every $a$ = 2–5 m span between them and carry a one-way roof slab. Each secondary beam brings its reaction $P = w_{sec}\\,S$ to the girder, where $w_{sec} = w_s\\,a + w_{g,sec}$. Three or more of them are smeared into an equivalent uniform load over the span, $w = w_g + \\Sigma P/L$ ($w_g$ = own weight of the girder): $\\Sigma P$ counts only the secondary beams **inside** the span — those standing over the columns send their reactions straight down into them. A secondary beam that is continuous over several girders is $S/12$ deep.",ar:"الكمرات بينها مسافة $S$؛ و**الكمرات المتشالة** كل $a$ = 2–5 م بحرها بينهم وشايلة بلاطة سقف في اتجاه واحد. كل كمرة متشالة بتجيب رد فعلها $P = w_{sec}\\,S$ للكمرة الشايلة، و $w_{sec} = w_s\\,a + w_{g,sec}$. ولو هما تلاتة أو أكتر بيتفرشوا لحمل موزع منتظم مكافئ على البحر، $w = w_g + \\Sigma P/L$ ($w_g$ = الوزن الذاتي للكمرة الشايلة): والـ $\\Sigma P$ بتعد الكمرات المتشالة اللي **جوه** البحر بس — واللي واقفة فوق الأعمدة ردود أفعالها بتنزل فيها على طول. والكمرة المتشالة المستمرة على كذا كمرة عمقها $S/12$."}},{t:"eq",tex:["P = (w_s\\,a + w_{g,sec})\\,S","w = w_g + \\dfrac{\\Sigma P}{L}"],caption:{en:"ΣP = the reactions of the n − 1 secondary beams inside a span of n panels (L = n·a); the beams over the columns go straight into them.",ar:"ΣP = ردود أفعال الـ n − 1 كمرة متشالة اللي جوه بحر فيه n باكية (L = n·a)؛ والكمرات اللي فوق الأعمدة بتنزل فيها على طول."}},{t:"p",text:{en:"**Edge and simple secondary beams.** An edge secondary beam carries half a strip: $w_{sec} = w_s\\,a/2 + w_{g,sec}$. And $P = w_{sec}\\,S$ is the reaction of a secondary beam that runs **continuous** over many girders. Where there are only **two** girders — a shed on four corner columns, for instance — every secondary beam is **simple** between them and hands each girder only its end reaction $w_{sec}\\,S/2$. **Example:** two 18 m girders 8 m apart, secondary beams 250 × 700 every 2.0 m, $w_s = 8$ kN/m²: $w_{sec} = 8\\times2.0 + 1.4\\times0.25\\times0.7\\times25 = 16 + 6.125 = 22.125$ kN/m → $P = 22.125\\times8/2 = 88.5$ kN on each girder, not $22.125\\times8 = 177$ kN.",ar:"**الكمرات المتشالة الطرفية والبسيطة.** الكمرة المتشالة الطرفية شايلة نص شريحة: $w_{sec} = w_s\\,a/2 + w_{g,sec}$. و $P = w_{sec}\\,S$ ده رد فعل كمرة متشالة **مستمرة** على كذا كمرة شايلة. ولما يبقى فيه كمرتين شايلين **بس** — هنجر على أربع أعمدة في الأركان مثلاً — كل كمرة متشالة بتبقى **بسيطة** بينهم وبتسلّم كل كمرة شايلة رد فعلها الطرفي بس $w_{sec}\\,S/2$. **مثال:** كمرتين شايلين 18 م بينهم 8 م، وكمرات متشالة 250 × 700 كل 2.0 م، و $w_s = 8$ kN/m²: $w_{sec} = 8\\times2.0 + 1.4\\times0.25\\times0.7\\times25 = 16 + 6.125 = 22.125$ kN/m ← $P = 22.125\\times8/2 = 88.5$ kN على كل كمرة شايلة، مش $22.125\\times8 = 177$ kN."}},{t:"p",text:{en:"**How close is the smearing?** It fits best when the secondary beams are many, roughly equal and evenly spaced. The point loads themselves bend a simple girder more: $n - 1$ equal loads at $L/n$ give $nPL/8$ at mid-span ($n$ even), against $(n - 1)PL/8$ when smeared. When a few heavy beams dominate, check the span with the point loads as well. **Example:** the 10 m girder of the first section: smeared, $w = 10 + 3\\times120/10 = 46$ kN/m → $wL^2/8 = 575$ kN·m; the three point loads themselves give $180\\times5 - 120\\times2.5 + 10\\times10^2/8 = 725$ kN·m, 26% more.",ar:"**الفرش ده قريب من الحقيقة لحد فين؟** أنسب ما يكون لما الكمرات المتشالة تبقى كتير ومتساوية تقريباً ومتوزعة بانتظام. والأحمال المركزة نفسها بتحني الكمرة البسيطة أكتر: $n - 1$ حمل متساوي على $L/n$ بيدّوا $nPL/8$ في نص البحر ($n$ زوجي)، قصاد $(n - 1)PL/8$ وهما مفروشين. ولما كام كمرة تقيلة يكونوا هما الغالبين، راجع البحر بالأحمال المركزة كمان. **مثال:** كمرة الـ 10 م بتاعة أول جزء: مفروشة، $w = 10 + 3\\times120/10 = 46$ kN/m ← $wL^2/8 = 575$ kN·m؛ والتلات أحمال المركزة نفسها بيدّوا $180\\times5 - 120\\times2.5 + 10\\times10^2/8 = 725$ kN·m، أكتر بـ 26%."}},{t:"quiz",q:{kind:"num",q:{en:"w_s = 8 kN/m², secondary beams every 2.5 m weighing 3 kN/m, girders 5 m apart. Reaction P of one secondary beam (kN)?",ar:"w_s = 8 kN/m²، وكمرات متشالة كل 2.5 م وزنها 3 kN/m، والكمرات الشايلة كل 5 م. رد فعل كمرة متشالة واحدة P (kN)؟"},answer:115,tol:.003,unit:"kN",explain:{en:"$(8\\times2.5 + 3)\\times5 = 23\\times5 = 115$ kN.",ar:"$(8\\times2.5 + 3)\\times5 = 23\\times5 = 115$ kN."}}}]},{id:"continuous",title:{en:"Continuous girders",ar:"الكمرات المستمرة"},blocks:[{t:"p",text:{en:"On medium or hard soil a girder may run continuously over its columns. Continuity lowers the span moment — for two equal spans from $wL^2/8$ to $9wL^2/128$ — but creates a hogging moment $wL^2/8$ over the middle column. Because its columns are hinged in effect, the girder is analysed as a continuous beam: moment distribution, three-moment equations, or the tables.",ar:"على تربة متوسطة أو قوية الكمرة ممكن تبقى مستمرة على أعمدتها. الاستمرار بيقلل عزم البحر — لبحرين متساويين من $wL^2/8$ لـ $9wL^2/128$ — بس بيعمل عزم سالب $wL^2/8$ فوق العمود الوسطاني. ولأن أعمدتها في الحقيقة مفصلية، الكمرة بتتحلل ككمرة مستمرة: توزيع العزوم، أو معادلة الثلاث عزوم، أو الجداول."}},{t:"eq",tex:["M_{support} = \\dfrac{wL^2}{8},\\qquad M_{span} = \\dfrac{9\\,wL^2}{128}"],caption:{en:"Two equal spans, uniform load, hinged ends.",ar:"بحرين متساويين، حمل موزع منتظم، وأطراف مفصلية."}},{t:"lab",lab:"hardycross",height:460,props:{preset:"two",missions:i},caption:{en:"Two equal spans by moment distribution: release the middle joint, carry over, repeat.",ar:"بحرين متساويين بتوزيع العزوم: فك العقدة الوسطانية، وانقل، وكرّر."}},{t:"quiz",q:{kind:"num",q:{en:"Two equal 8 m spans, w = 40 kN/m. Moment over the middle support (kN·m)?",ar:"بحرين متساويين 8 م، و w = 40 kN/m. العزم فوق الركيزة الوسطية (kN·m)؟"},answer:320,tol:.003,unit:"kN·m",explain:{en:"$wL^2/8 = 40\\times64/8 = 320$ kN·m.",ar:"$wL^2/8 = 40\\times64/8 = 320$ kN·m."}}}]},{id:"gerber",title:{en:"Cantilevers and hinges at L/5",ar:"الكوابيل والمفصلات عند L/5"},blocks:[{t:"p",text:{en:"**Cantilevers** beyond the end columns hog the supports and relieve the span. In the lab's 10 m girder two 2 m cantilevers bring the span moment from 725 down to 585 kN·m. On **weak soil** a continuous girder is made determinate by **intermediate hinges at about L/5** from a support — near the natural zero-moment point, so the moments change little, and a settling column no longer changes them at all. The piece between two hinges is a **floating (suspended) bay**. For the two 10 m spans with a hinge 2 m into the second span, the support takes 550 kN·m and both spans 450 kN·m, against 675 and 390.2 kN·m when continuous.",ar:"**الكوابيل** بعد الأعمدة الطرفية بتعمل عزم سالب عند الركائز وبتريّح البحر. في كمرة المعمل 10 م كابولين 2 م بينزّلوا عزم البحر من 725 لـ 585 kN·m. وعلى **التربة الضعيفة** الكمرة المستمرة بتتعمل محددة بـ**مفصلات وسطية حوالي L/5** من الركيزة — قريب من نقطة العزم الصفري الطبيعية، فالعزوم بتتغيّر شوية، والعمود اللي بيهبط مابقاش بيغيّرها خالص. والجزء اللي بين مفصلتين **باكية عائمة (معلّقة)**. ولبحرين 10 م بمفصلة على بعد 2 م جوه البحر التاني، الركيزة بتاخد 550 kN·m والبحرين 450 kN·m، قصاد 675 و 390.2 kN·m وهي مستمرة."}},{t:"p",text:{en:"**A girder with cantilevers that carries a floating bay** — on weak soil, a span whose cantilever tips carry a suspended bay on halving joints with 2 cm gaps — takes the larger of its two depth rules, $t = \\max(L/12,\\ L_c/5)$. **Example:** 12 m spans with 3.5 m cantilevers carrying a 9 m floating bay: $\\max(1.0,\\ 0.70) = 1.0$ m; with 6 m cantilevers the cantilever governs, $6/5 = 1.2$ m.",ar:"**الكمرة بكوابيل اللي شايلة باكية عائمة** — على تربة ضعيفة، بحر أطراف كوابيله شايلة باكية معلّقة على وصلات نص على نص بفواصل 2 سم — بتاخد الأكبر من قاعدتين العمق بتوعها، $t = \\max(L/12,\\ L_c/5)$. **مثال:** بحور 12 م بكوابيل 3.5 م شايلة باكية عائمة 9 م: $\\max(1.0,\\ 0.70) = 1.0$ م؛ وبكوابيل 6 م الكابولي هو اللي بيحكم، $6/5 = 1.2$ م."}},{t:"lab",lab:"frame",height:470,props:{template:"girder",params:{joint:"hinged",sys:"cont"},lockTemplate:!0,missions:o},caption:{en:"The girder as continuous, with cantilevers, or with a hinge at L/5.",ar:"الكمرة مستمرة، أو بكوابيل، أو بمفصلة عند L/5."}},{t:"quiz",q:{kind:"mcq",q:{en:"Why is the intermediate hinge placed near L/5 from a support?",ar:"ليه المفصلة الوسطية بتتحط قريب من L/5 من الركيزة؟"},options:[{en:"the continuous girder has little moment there anyway",ar:"الكمرة المستمرة عزمها هناك صغير أصلاً"},{en:"the shear is largest there",ar:"القص هناك أكبر حاجة"},{en:"it doubles the span moment",ar:"بتضاعف عزم البحر"}],answer:0,explain:{en:"A hinge where the moment is already near zero changes the moment diagram least.",ar:"المفصلة في مكان العزم فيه قريب من الصفر أصلاً بتغيّر منحنى العزوم أقل حاجة."}}}]},{id:"haunch",title:{en:"Girders of variable depth",ar:"الكمرات متغيرة العمق"},blocks:[{t:"p",text:{en:"A continuous girder needs its depth mainly over the supports. So it is given a **haunch**: with $t = L/12$ as the reference, the depth grows to $1.2t$ over the supports and drops to $0.8t$ in the span, the haunch sloping 1:4 (so it is $4\\times0.4t = 1.6t$ long). The deeper ends are stiffer and attract moment: in the lab a fixed-ended 12 m span under 60 kN/m goes from 720 to 789.7 kN·m at the supports and from 360 to 290.3 kN·m at mid-span — the moment moves to where the depth was added.",ar:"الكمرة المستمرة محتاجة عمقها أساساً فوق الركائز. علشان كده بنديها **فيونكة**: و $t = L/12$ هو المرجع، العمق بيزيد لـ $1.2t$ فوق الركائز وبيقل لـ $0.8t$ في البحر، وميل الفيونكة 1:4 (يعني طولها $4\\times0.4t = 1.6t$). الأطراف الأعمق أجسأ وبتجذب العزم: في المعمل بحر 12 م ثابت الطرفين تحت 60 kN/m بيروح من 720 لـ 789.7 kN·m عند الركائز ومن 360 لـ 290.3 kN·m في النص — العزم بيروح للمكان اللي زودنا فيه العمق."}},{t:"eq",tex:["t = \\dfrac{L}{12},\\qquad t_{support} = 1.2\\,t,\\qquad t_{span} = 0.8\\,t,\\qquad l_h = 4\\,(1.2t - 0.8t) = 1.6\\,t"]},{t:"lab",lab:"frame",height:470,props:{template:"haunch",lockTemplate:!0,missions:m},caption:{en:"Uniform or haunched, one fixed-ended span or two spans with the haunch over the middle support.",ar:"منتظمة أو بفيونكات، بحر واحد ثابت الطرفين أو بحرين والفيونكة فوق الركيزة الوسطية."}},{t:"quiz",q:{kind:"num",q:{en:"A 15 m haunched girder by the rule. Depth over the support (m)?",ar:"كمرة 15 م بفيونكة بالقاعدة. العمق فوق الركيزة (م)؟"},answer:1.5,tol:.003,unit:"m",explain:{en:"$t = 15/12 = 1.25$ m; $1.2t = 1.5$ m (and $0.8t = 1.0$ m in the span).",ar:"$t = 15/12 = 1.25$ م؛ و $1.2t = 1.5$ م (و $0.8t = 1.0$ م في البحر)."}}}]},{id:"skylight",title:{en:"Girders with a sky-light",ar:"الكمرات بشبابيك إضاءة (شخشيخة)"},blocks:[{t:"p",text:{en:"To bring daylight into a deep hall, a strip of the roof is raised: short **posts** stand on the girder at both sides of the opening and a light **simple beam** spans between their tops, carrying the raised roof; vertical glazing closes the gap. For the girder the sky-light is just two point loads (the post reactions) instead of the slab it replaced — and a softer section where the slab is missing.",ar:"علشان تدخل إضاءة طبيعية لصالة عميقة، شريحة من السقف بتتعلّى: **أعمدة قصيرة** واقفة على الكمرة على جنبين الفتحة و**كمرة بسيطة** خفيفة بحرها بين رؤوسهم، شايلة السقف المرفوع؛ والإزاز الرأسي بيقفل الفرق. وبالنسبة للكمرة الشايلة الشبابيك دي مجرد حملين مركزين (ردود أفعال الأعمدة القصيرة) بدل البلاطة اللي اتشالت — وقطاع أطرى في المكان اللي مفيهوش بلاطة."}},{t:"p",text:{en:"Each of the two point loads is $R_1 + R_2 + R_3$. Down the post come $R_1$, the reaction of the lantern's cross beam on the post line (simple over the lantern width, $w\\,L/2$), and $R_2$, that of the lantern's edge beam along the hall ($w_a\\,S$, its small cantilever strip included); at the post foot the main roof's edge beam at the opening adds $R_3 = w_a\\,S$. Under the opening the girder has no slab: design that part of the span as a **rectangular section**, without a flange. **Example:** girders 6 m apart under a lantern 4 m wide: a cross beam of 12 kN/m → $R_1 = 12\\times4/2 = 24$ kN; a lantern edge beam of 14 kN/m → $R_2 = 14\\times6 = 84$ kN; a main-roof edge beam of 16 kN/m → $R_3 = 16\\times6 = 96$ kN; $P = 24 + 84 + 96 = 204$ kN on each side of the opening.",ar:"كل حمل من الحملين المركزين هو $R_1 + R_2 + R_3$. نازل في العمود القصير $R_1$، رد فعل الكمرة العرضية بتاعة الشخشيخة على خط الأعمدة القصيرة (بسيطة على عرض الشخشيخة، $w\\,L/2$)، و $R_2$، رد فعل الكمرة الطرفية للشخشيخة بطول الصالة ($w_a\\,S$، ومعاها شريحة الكابولي الصغيرة)؛ وعند رجل العمود القصير الكمرة الطرفية للسقف الرئيسي عند الفتحة بتزوّد $R_3 = w_a\\,S$. وتحت الفتحة الكمرة مفيهاش بلاطة: صمم الجزء ده من البحر **قطاع مستطيل**، من غير شفة. **مثال:** كمرات كل 6 م تحت شخشيخة عرضها 4 م: كمرة عرضية 12 kN/m ← $R_1 = 12\\times4/2 = 24$ kN؛ وكمرة طرفية للشخشيخة 14 kN/m ← $R_2 = 14\\times6 = 84$ kN؛ وكمرة طرفية للسقف الرئيسي 16 kN/m ← $R_3 = 16\\times6 = 96$ kN؛ و $P = 24 + 84 + 96 = 204$ kN على كل ناحية من الفتحة."}},{t:"p",text:{en:"**Two roof levels on one girder.** A raised strip is a second roof level, and the step $\\Delta$ between the two slabs decides how the girder carries it. Up to $\\Delta = 2.0$ m the girder carries **both slabs directly** — the high one on its top, the low one at its soffit — so it must be at least $t \\ge \\Delta + t_s$ deep ($t_s$ = thickness of the low slab), and the beams of the low roof are made **inverted (upstand)** so that they do not push the girder deeper still. Beyond 2.0 m that depth would be wasted: the girder carries one slab directly and the other through a beam — on **posts** standing on the girder and tied along it by a **tie beam**, or on **hangers** (posts up to about 4 m, hangers beyond — the arch-girder episode) — and its depth no longer depends on $\\Delta$. **Example:** a 12 m simple girder ($L/10 = 1.20$ m) under two roofs 1.4 m apart with a 120 mm low slab: $t \\ge 1.4 + 0.12 = 1.52$ m → 1.55 m — here the step, not the span, sets the depth. With a 2.6 m step the girder keeps its 1.20 m and the high roof goes onto posts. Where the level changes at **every** girder line — high and low bays alternating — the slab bars of each bay are hooked into the two girders that carry it, and the low bays get the inverted beams.",ar:"**منسوبين سقف على كمرة واحدة.** الشريحة المرفوعة منسوب سقف تاني، وفرق المنسوب $\\Delta$ بين البلاطتين هو اللي بيحدد الكمرة هتشيلها إزاي. لحد $\\Delta = 2.0$ م الكمرة بتشيل **البلاطتين على طول** — العالية فوقها، والواطية عند بطنها — فعمقها لازم يبقى على الأقل $t \\ge \\Delta + t_s$ ($t_s$ = تخانة البلاطة الواطية)، وكمرات السقف الواطي بتتعمل **مقلوبة** علشان ماتزوّدش عمق الكمرة أكتر. وبعد 2.0 م العمق ده هيبقى خسارة: الكمرة بتشيل بلاطة على طول والتانية عن طريق كمرة — على **قوائم** واقفة على الكمرة ومربوطة بطولها بـ**كمرة تربيط**، أو على **معلّقات** (القوائم لحد حوالي 4 م، والمعلّقات بعد كده — حلقة الكمرات المقوّسة) — وعمقها مابقاش بيعتمد على $\\Delta$. **مثال:** كمرة بسيطة 12 م ($L/10 = 1.20$ م) تحت سقفين بينهم 1.4 م وبلاطة واطية 120 مم: $t \\ge 1.4 + 0.12 = 1.52$ م ← 1.55 م — هنا الدرجة، مش البحر، هي اللي حددت العمق. وبدرجة 2.6 م الكمرة بتحافظ على الـ 1.20 م بتاعتها والسقف العالي بيركب على قوائم. ولما المنسوب يتغيّر عند **كل** خط كمرات — بواكي عالية وواطية بالتبادل — حديد بلاطة كل باكية بيخلص بجنش جوه الكمرتين اللي شايلينها، والبواكي الواطية بتاخد الكمرات المقلوبة."}},{t:"quiz",q:{kind:"mcq",q:{en:"For the girder, a raised sky-light on posts is…",ar:"بالنسبة للكمرة الشايلة، شبابيك الإضاءة المرفوعة على أعمدة قصيرة هي…"},options:[{en:"two point loads from the posts",ar:"حملين مركزين من الأعمدة القصيرة"},{en:"an extra support in the span",ar:"ركيزة زيادة في البحر"},{en:"nothing — it hangs from the roof",ar:"ولا حاجة — دي متعلّقة في السقف"}],answer:0,explain:{en:"The simple beam of the sky-light rests on the posts, and the posts stand on the girder.",ar:"الكمرة البسيطة بتاعة الشبابيك راكبة على الأعمدة القصيرة، والأعمدة واقفة على الكمرة."}}}]},{id:"neoprene",title:{en:"Girders on real supports",ar:"الكمرات على ركائز حقيقية"},blocks:[{t:"p",text:{en:'For 12–40 m a girder can still be "a beam on its columns" if it sits on **real supports**: laminated neoprene pads that let it rotate (and, on one side, slide), so the columns receive forces but no moment and the girder no frame action. Rules: $t_G = L/10$; columns $t_c = H/9 \\to H/8$; a T-section up to 20 m, an I-section beyond to save own weight. The pad is about $t/3$ long with steel laminates; a sliding (roller) bearing moves freely, a hinged one gets dowel bars through the pad.',ar:"من 12 لـ 40 م الكمرة ممكن تفضل «كمرة على أعمدتها» لو راكبة على **ركائز حقيقية**: ألواح نيوبرين بطبقات بتسيبها تلف (ومن ناحية واحدة تتزحلق)، فالأعمدة بتاخد قوى من غير عزم والكمرة من غير عمل إطار. القواعد: $t_G = L/10$؛ والأعمدة $t_c = H/9 \\to H/8$؛ وقطاع T لحد 20 م، وقطاع I بعد كده علشان يوفّر الوزن الذاتي. واللوح طوله حوالي $t/3$ بطبقات صلب؛ والركيزة المنزلقة (المتحركة) بتتحرك بحرية، والمفصلية بتاخد أشاير عابرة اللوح."}},{t:"p",text:{en:"**Example:** a 24 m girder on 7 m columns: $t_G = 2.4$ m (an I-section), columns $7/9 = 0.78$ to $7/8 = 0.88$ m deep, a pad about 0.8 m long.",ar:"**مثال:** كمرة 24 م على أعمدة 7 م: $t_G = 2.4$ م (قطاع I)، والأعمدة عمقها من $7/9 = 0.78$ لـ $7/8 = 0.88$ م، ولوح طوله حوالي 0.8 م."}},{t:"steps",items:[{en:"**Hinge or roller.** A real hinge is a bearing pad with a dowel through it into the column; a real roller is the pad alone. **There is no $wL^2/24$ on real supports**: the ends are truly free, so the girder needs no top steel for end moments — only stirrup hangers there — and its columns receive no moment from it.",ar:"**مفصلة ولا ركيزة متحركة.** المفصلة الحقيقية لوح ارتكاز وأشاير عابرة اللوح لجوه العمود؛ والركيزة المتحركة الحقيقية اللوح لوحده. **مفيش $wL^2/24$ على الركائز الحقيقية**: الأطراف حرة فعلاً، فالكمرة مش محتاجة حديد علوي لعزوم أطراف — كانات تعليق بس هناك — وأعمدتها مابتاخدش منها عزم."},{en:"**Steering a thrust.** A girder line next to an untied thrusting roof (an arch slab, a saw-tooth) receives $X\\cdot S$ on one side. Give each girder a real hinge at the thrust side and a real roller at the far end: the whole $X\\cdot S$ goes into the column under the hinge and straight down to its footing — make that column about **1.5 t** and shift its footing against its moment; the girder and the other column get nothing. Cast monolithically instead, one column made about **2.5 t** draws almost all of the push by its stiffness ($\\propto t^3$).",ar:"**توجيه الدفع.** خط كمرات جنب سقف بيزق ومن غير شداد (بلاطة مقوّسة أو منشاري) بياخد $X\\cdot S$ من ناحية واحدة. ادّي كل كمرة مفصلة حقيقية ناحية الدفع وركيزة متحركة حقيقية في الطرف التاني: الـ $X\\cdot S$ كلها بتروح للعمود اللي تحت المفصلة وتنزل على طول لقاعدته — خلّي العمود ده حوالي **1.5 t** ورحّل قاعدته عكس عزمه؛ والكمرة والعمود التاني مابياخدوش حاجة. ولو اتصبت مع بعض، عمود واحد عمقه حوالي **2.5 t** بيسحب تقريباً الزقة كلها بجساءته ($\\propto t^3$)."},{en:"**An interior column carrying two girders** gets a forked (Y-shaped) head: two short cantilevers, one girder on a hinge, the other on a roller, with a 2 cm gap between their ends (the joints episode).",ar:"**العمود الوسطاني اللي شايل كمرتين** بياخد راس متفرّعة (على شكل Y): كابولين قصيرين، كمرة على مفصلة والتانية على ركيزة متحركة، وبين أطرافهم 2 سم (حلقة الفواصل)."}]},{t:"p",text:{en:"**Example.** An untied arch slab pushes $X = 15$ kN/m on a girder line with columns every 5 m, 6 m high, normally 0.6 m deep: $X\\cdot S = 75$ kN → $M = 75\\times6 = 450$ kN·m at the foot of the hinged-side column, made $1.5\\times0.6 = 0.9$ m deep. Cast monolithically, a $2.5\\times0.6 = 1.5$ m column takes $2.5^3/(2.5^3 + 1) = 94.0\\%$ of the push (70.5 kN); a column only 1.5 times deeper would take 77.1%.",ar:"**مثال.** بلاطة مقوّسة من غير شداد بتزق $X = 15$ kN/m على خط كمرات أعمدته كل 5 م، ارتفاعها 6 م وعمقها العادي 0.6 م: $X\\cdot S = 75$ kN ← $M = 75\\times6 = 450$ kN·m عند رجل العمود اللي ناحية المفصلة، واتعمل عمقه $1.5\\times0.6 = 0.9$ م. ولو اتصبت مع بعض، عمود $2.5\\times0.6 = 1.5$ م بياخد $2.5^3/(2.5^3 + 1) = 94.0\\%$ من الزقة (70.5 kN)؛ وعمود أعمق مرة ونص بس كان هياخد 77.1%."}},{t:"quiz",q:{kind:"num",q:{en:"A 30 m girder on neoprene bearings. Depth by the rule (m)?",ar:"كمرة 30 م على ركائز نيوبرين. العمق بالقاعدة (م)؟"},answer:3,tol:.003,unit:"m",explain:{en:"$L/10 = 3.0$ m — an I-section, since the span exceeds 20 m.",ar:"$L/10 = 3.0$ م — قطاع I، لأن البحر أكبر من 20 م."}}}]},{id:"carry",title:{en:"A girder that carries a frame",ar:"كمرة شايلة إطار"},blocks:[{t:"p",text:{en:"A hall may stand on another system — an upper hall whose frames rest on a continuous girder below, for instance. Make the carried frame **two-hinged, not fixed — even up to 24 m**: a fixed frame would lock frame and girder into one **closed frame**, very hard to solve and pushing moments into the girder.",ar:"الصالة ممكن تقف على نظام تاني — صالة فوق إطاراتها راكبة على كمرة مستمرة تحت مثلاً. خلّي الإطار المحمول **ذو مفصلين، مش ثابت — حتى لو بحره 24 م**: الإطار الثابت هيقفل الإطار والكمرة مع بعض في **إطار مقفول** واحد، صعب جداً في الحل وبيدخّل عزوم في الكمرة."}},{t:"steps",items:[{en:"The hinges pass **no moment**; they pass $Y$ down and $X$ outwards. Between the two feet the girder is pulled by $X$: it is the frame's **tie**, designed for **M + T**. Its B.M.D is that of the continuous beam under the reactions $Y$, and the columns under the frame feet are in compression.",ar:"المفصلات **مابتنقلش عزم**؛ بتنقل $Y$ لتحت و $X$ لبره. وبين الرجلين الكمرة بتتشد بـ $X$: هي **شداد** الإطار، وبتتصمم على **M + T**. ومنحنى عزومها هو بتاع الكمرة المستمرة تحت ردود الأفعال $Y$، والأعمدة اللي تحت رجلين الإطار في الضغط."},{en:"A **cantilever frame** carried by another system is the opposite case: it must be **fixed** to it — on a hinge it is unstable.",ar:"و**الإطار الكابولي** المحمول على نظام تاني عكس كده: لازم يبقى **مثبت** فيه — على مفصلة بيبقى غير مستقر."},{en:"In a saw-tooth roof, a girder that replaces a middle column carries the middle Y-beam and, with all bays tied, the tie force $X\\cdot S$ as well → M + T (the saw-tooth episode).",ar:"وفي السقف المنشاري، الكمرة اللي بتتحط بدل عمود في النص بتشيل كمرة Y اللي في النص، ولو كل البواكي بشدادات بتشيل قوة الشداد $X\\cdot S$ كمان ← M + T (حلقة المنشاري)."},{en:"With **no ties in the end bays**, that girder receives **no tension** and is designed for **M only**; the end columns then take $X\\cdot S$ at their heads — their footings are shifted outwards and the columns made deeper. **Example:** $X\\cdot S = 25$ kN on end columns 6 m high gives $25\\times6 = 150$ kN·m at each base, where tying every bay would instead put 25 kN of tension into the girder.",ar:"ولو **مفيش شدادات في البواكي الطرفية**، الكمرة دي **مابتاخدش شد** وبتتصمم على **M بس**؛ والأعمدة الطرفية ساعتها بتاخد $X\\cdot S$ عند رؤوسها — قواعدها بتترحّل لبره والأعمدة بتتعمّق. **مثال:** $X\\cdot S = 25$ kN على أعمدة طرفية ارتفاعها 6 م بتدّي $25\\times6 = 150$ kN·m عند كل قاعدة، في حين إن الشدادات في كل البواكي كانت هتحط 25 kN شد في الكمرة بدل كده."},{en:"Under a saw-tooth roof a line of girders can also stand in for whole column lines: **simple girders at unequal spacing**, one under each slab edge, with ties across every tooth (at the girder ends and at mid-span) so that the last girders receive no horizontal force, and tie beams across the flat strips between the girder pairs; or, where every other column is left out, the slab-type teeth rest on a **continuous girder**, $L/12$ deep like any continuous girder (the saw-tooth episode).",ar:"وتحت السقف المنشاري خط كمرات ممكن يقوم مقام خطوط أعمدة كاملة: **كمرات بسيطة على مسافات مش متساوية**، واحدة تحت كل حرف بلاطة، وشدادات عابرة كل سنّة (عند أطراف الكمرات وفي نصها) علشان آخر كمرات ماياخدوش قوة أفقية، و**كمرات تربيط** عابرة الشرايح المسطحة اللي بين كل كمرتين؛ أو، لما الأعمدة تتشال بالتبادل، أسنان نوع البلاطة بتركب على **كمرة مستمرة** عمقها $L/12$ زي أي كمرة مستمرة (حلقة المنشاري)."},{en:"At a **step in the roof** a girder may rest on the column of a frame or of another girder: it stays simple, hands that column only its reaction, and its bars are hooked inside the column (the joints episode).",ar:"وعند **درجة في السقف** الكمرة ممكن تركب على عمود إطار أو عمود كمرة تانية: بتفضل بسيطة، وبتسلّم العمود ده رد فعلها بس، وحديدها بيخلص بجنش جوه العمود (حلقة الفواصل)."}]},{t:"p",text:{en:"**Example.** A two-hinged frame 16 m wide and 4 m high ($I_b = 2I_c$, so $k = 2\\times4/16 = 0.5$) with $w = 30$ kN/m stands on a continuous girder: $X = wL^2/(4h\\,(2k + 3)) = 30\\times256/64 = 120$ kN and $Y = 240$ kN at each foot. The girder carries $T = 120$ kN between the feet — an exact analysis of frame and girder together gives the same — and needs $120\\times10^3/347.8 = 345$ mm² of steel for it on top of its bending steel; the knees take $120\\times4 = 480$ kN·m.",ar:"**مثال.** إطار ذو مفصلين عرضه 16 م وارتفاعه 4 م ($I_b = 2I_c$، يعني $k = 2\\times4/16 = 0.5$) و $w = 30$ kN/m واقف على كمرة مستمرة: $X = wL^2/(4h\\,(2k + 3)) = 30\\times256/64 = 120$ kN و $Y = 240$ kN عند كل رجل. الكمرة شايلة $T = 120$ kN بين الرجلين — والتحليل المضبوط للإطار والكمرة مع بعض بيدّي نفس القيمة — ومحتاجة $120\\times10^3/347.8 = 345$ مم² حديد ليها فوق حديد الانحناء؛ والأركان بتاخد $120\\times4 = 480$ kN·m."}},{t:"quiz",q:{kind:"tf",q:{en:"A two-hinged frame standing on a girder puts the girder in compression between its feet.",ar:"الإطار ذو المفصلين الواقف على كمرة بيخلّي الكمرة في ضغط بين رجليه."},answer:!1,explain:{en:"The feet push outwards; the girder holds them together, so it is in tension X — it is the frame's tie.",ar:"الرجلين بيزقوا لبره؛ والكمرة ماسكاهم في بعض، فهي في شد X — هي شداد الإطار."}}}]},{id:"details",title:{en:"Reinforcement details of girders",ar:"تفاصيل تسليح الكمرات"},blocks:[{t:"steps",items:[{en:"Girders deeper than 700 mm get **shrinkage (side) bars** on both faces.",ar:"الكمرات الأعمق من 700 مم بتاخد **أسياخ انكماش (جانبية)** على الوشين."},{en:"**Stirrup hangers** where the secondary beams hang on the girder: the reaction is lifted into the compression zone.",ar:"**كانات تعليق** في أماكن تعليق الكمرات المتشالة على الكمرة: رد الفعل بيترفع لمنطقة الضغط."},{en:"At least **half the span steel** runs through into the supports (continuity), and the top steel over a column that is treated as a hinge is designed for $wL^2/24$.",ar:"على الأقل **نص حديد البحر** بيكمّل جوه الركائز (الاستمرار)، والحديد العلوي فوق العمود اللي معتبرينه مفصلة بيتصمم على $wL^2/24$."},{en:"The columns are designed for their normal force and the moment they receive, with the **additional moment of buckling** where they are slender.",ar:"الأعمدة بتتصمم على قوتها العمودية والعزم اللي بيوصلها، مع **العزم الإضافي للانبعاج** لو نحيفة."},{en:"**A girder framing into a frame column without a corbel**: its bars run into the column **straight**, with no bends down the column faces, and end in a hook inside the column core, so the joint passes no moment — the girder end works as a hinge by detailing alone.",ar:"**كمرة داخلة في عمود إطار من غير كابولي قصير**: حديدها بيدخل العمود **مستقيم**، من غير ما يتني على وشوش العمود، وبيخلص بجنش جوه قلب العمود، فالوصلة مابتنقلش عزم — طرف الكمرة بيشتغل مفصلة بالتفاصيل لوحدها."},{en:"**The flange in the span.** Under a solid slab an interior girder is designed in its span as a **T-section** and an edge girder, with the slab on one side only, as an **L-section** (widths below). $K\\,L$ is the distance between the points of zero moment: $K = 1.0$ for a simple girder, 0.8 for a span continuous at one end, 0.7 for a span continuous at both ends or the beam of a frame.",ar:"**الشفة في البحر.** تحت بلاطة مصمتة الكمرة الوسطية بتتصمم في بحرها **قطاع T**، والكمرة الطرفية اللي البلاطة من ناحية واحدة بس منها **قطاع L** (العروض تحت). و $K\\,L$ هي المسافة بين نقطتين العزم الصفري: $K = 1.0$ للكمرة البسيطة، و 0.8 لبحر مستمر من طرف واحد، و 0.7 لبحر مستمر من الطرفين أو لكمرة إطار."},{en:"**Under a hollow-block roof** the blocks leave no solid flange in compression next to the girder, so its span is designed as a **rectangular section** $b\\times t$.",ar:"**تحت سقف هوردي** البلوكات مابتسيبش شفة مصمتة في الضغط جنب الكمرة، فبحرها بيتصمم **قطاع مستطيل** $b\\times t$."}]},{t:"eq",tex:["B_T = \\min\\left(S,\\ 16\\,t_s + b,\\ \\dfrac{K\\,L}{5} + b\\right)","B_L = \\min\\left(\\dfrac{S}{2},\\ 6\\,t_s + b,\\ \\dfrac{K\\,L}{10} + b\\right)"],caption:{en:"Effective flange width of a T-section (interior girder) and of an L-section (edge girder); S = spacing of the girders, t_s = slab thickness, b = web width.",ar:"العرض الفعّال للشفة في قطاع T (كمرة وسطية) وفي قطاع L (كمرة طرفية)؛ S = المسافة بين الكمرات، و t_s = تخانة البلاطة، و b = عرض العصب."}},{t:"p",text:{en:"**Example** ($f_{cu} = 25$, $f_y = 400$). A simple girder of 12 m, 300 × 1200 ($d = 1100$ mm), girders 5 m apart under a 120 mm solid slab, $M = 50\\times12^2/8 = 900$ kN·m. **Interior girder:** $B_T = \\min(5000,\\ 16\\times120 + 300 = 2220,\\ 12000/5 + 300 = 2700) = 2220$ mm; $C_1 = 1100/\\sqrt{900\\times10^6/(25\\times2220)} = 8.64$ → $J = 0.826$, the compression block stays inside the slab, $A_s = 2476$ mm² → 7Ø22 (2661 mm²). Were it the beam of a frame ($K = 0.7$), the third limit would govern: $0.7\\times12000/5 + 300 = 1980$ mm. **Edge girder:** $B_L = \\min(2500,\\ 6\\times120 + 300 = 1020,\\ 12000/10 + 300 = 1500) = 1020$ mm; $C_1 = 5.86$, still $J = 0.826$ and the same 2476 mm². **Under a hollow-block roof:** $C_1 = 1100/\\sqrt{900\\times10^6/(25\\times300)} = 3.18$, $J = 0.759$, $A_s = 2695$ mm² → 8Ø22 (3041 mm²).",ar:"**مثال** ($f_{cu} = 25$، و $f_y = 400$). كمرة بسيطة 12 م، مقاس 300 × 1200 ($d = 1100$ مم)، والكمرات كل 5 م تحت بلاطة مصمتة 120 مم، و $M = 50\\times12^2/8 = 900$ kN·m. **الكمرة الوسطية:** $B_T = \\min(5000,\\ 16\\times120 + 300 = 2220,\\ 12000/5 + 300 = 2700) = 2220$ مم؛ و $C_1 = 1100/\\sqrt{900\\times10^6/(25\\times2220)} = 8.64$ ← $J = 0.826$، ومنطقة الضغط بتفضل جوه البلاطة، و $A_s = 2476$ مم² ← 7Ø22 (2661 مم²). ولو كانت كمرة إطار ($K = 0.7$)، الحد التالت هو اللي هيحكم: $0.7\\times12000/5 + 300 = 1980$ مم. **الكمرة الطرفية:** $B_L = \\min(2500,\\ 6\\times120 + 300 = 1020,\\ 12000/10 + 300 = 1500) = 1020$ مم؛ و $C_1 = 5.86$، ولسه $J = 0.826$ ونفس الـ 2476 مم². **تحت سقف هوردي:** $C_1 = 1100/\\sqrt{900\\times10^6/(25\\times300)} = 3.18$، و $J = 0.759$، و $A_s = 2695$ مم² ← 8Ø22 (3041 مم²)."}},{t:"quiz",q:{kind:"tf",q:{en:"A 750 mm deep girder needs side (shrinkage) bars.",ar:"كمرة عمقها 750 مم محتاجة أسياخ جانبية (انكماش)."},answer:!0,explain:{en:"Beyond 700 mm the web between the top and bottom bars would crack from shrinkage.",ar:"بعد 700 مم العصب اللي بين الحديد العلوي والسفلي هيتشرخ من الانكماش."}}}]},{id:"example",title:{en:"Worked example: a hall on continuous girders",ar:"مثال محلول: صالة على كمرات مستمرة"},blocks:[{t:"p",text:{en:"A roof 18 m wide is covered by girders continuous over two 9 m spans, spaced $S = 6.0$ m; secondary beams every $a = 2.25$ m; F.C. = 2.0, L.L. = 1.0 kN/m², $f_{cu} = 25$, $f_y = 400$ N/mm².",ar:"سقف عرضه 18 م متغطي بكمرات مستمرة على بحرين 9 م، بينها $S = 6.0$ م؛ وكمرات متشالة كل $a = 2.25$ م؛ و F.C. = 2.0، و L.L. = 1.0 kN/m²، و $f_{cu} = 25$، و $f_y = 400$ N/mm²."}},{t:"steps",items:[{en:"**Dimensions.** $t_G = 9/12 = 0.75$ m, $b = \\max(0.30,\\ 6.0/20) = 0.30$ m; columns $0.7\\times0.75 = 0.525 \\to 0.55$ m; secondary beams $6.0/12 = 0.50$ → 250 × 500; slab $2250/30 = 75 \\to 120$ mm.",ar:"**الأبعاد.** $t_G = 9/12 = 0.75$ م، و $b = \\max(0.30,\\ 6.0/20) = 0.30$ م؛ والأعمدة $0.7\\times0.75 = 0.525 \\to 0.55$ م؛ والكمرات المتشالة $6.0/12 = 0.50$ ← 250 × 500؛ والبلاطة $2250/30 = 75 \\to 120$ مم."},{en:"**Slab.** $w_s = 1.4\\,(0.12\\times25 + 2.0) + 1.6\\times1.0 = 8.6$ kN/m². Strip moments: $wL^2/10 = 4.354$ (first interior support), $wL^2/12 = 3.628$, $wL^2/24 = 1.814$ kN·m/m. With $d = 100$ mm: $C_1 = 100/\\sqrt{4.354\\times10^6/25000} = 7.58$ → $J = 0.826$, $A_s = 131.8$ mm²/m, below the minimum 150 → 5Ø10/m.",ar:"**البلاطة.** $w_s = 1.4\\,(0.12\\times25 + 2.0) + 1.6\\times1.0 = 8.6$ kN/m². عزوم الشريحة: $wL^2/10 = 4.354$ (أول ركيزة وسطية)، و $wL^2/12 = 3.628$، و $wL^2/24 = 1.814$ kN·m/m. وبـ $d = 100$ مم: $C_1 = 100/\\sqrt{4.354\\times10^6/25000} = 7.58$ ← $J = 0.826$، و $A_s = 131.8$ مم²/م، أقل من الحد الأدنى 150 ← 5Ø10/م."},{en:"**Loads on the girder.** Secondary beam: $1.4\\times0.25\\times0.38\\times25 = 3.325$ kN/m, $w_{sec} = 8.6\\times2.25 + 3.325 = 22.675$ kN/m, $P = 22.675\\times6.0 = 136.05$ kN. Girder own weight $1.4\\times0.3\\times0.63\\times25 = 6.615$ kN/m. Each 9 m span has three secondary beams inside it — the ones over the columns go straight down — so $w = 6.615 + 3\\times136.05/9 = 51.97$ kN/m.",ar:"**الأحمال على الكمرة.** الكمرة المتشالة: $1.4\\times0.25\\times0.38\\times25 = 3.325$ kN/m، و $w_{sec} = 8.6\\times2.25 + 3.325 = 22.675$ kN/m، و $P = 22.675\\times6.0 = 136.05$ kN. ووزن الكمرة $1.4\\times0.3\\times0.63\\times25 = 6.615$ kN/m. وكل بحر 9 م جواه تلات كمرات متشالة — واللي فوق الأعمدة بتنزل فيها على طول — يبقى $w = 6.615 + 3\\times136.05/9 = 51.97$ kN/m."},{en:"**Moments.** Support $wL^2/8 = 526.1$, span $9wL^2/128 = 296.0$ kN·m; edge columns and their top steel $wL^2/24 = 175.4$ kN·m.",ar:"**العزوم.** الركيزة $wL^2/8 = 526.1$، والبحر $9wL^2/128 = 296.0$ kN·m؛ والأعمدة الطرفية وحديدها العلوي $wL^2/24 = 175.4$ kN·m."},{en:"**Support section.** $d = 700$: $C_1 = 700/\\sqrt{526.1\\times10^6/(25\\times300)} = 2.64 < C_{1,min} = 2.83$ — too shallow for $L/12$. Haunch it: $1.2t = 0.90$ m over the middle column, $0.8t = 0.60$ m in the spans, haunches 1.2 m long. The haunch attracts moment — the lab gives 607.5 kN·m at the support and 266.2 in the spans. With $d = 850$: $C_1 = 2.99$, $J = 0.742$, $A_s = 2409$ mm² → 5Ø25 (2454 mm²).",ar:"**قطاع الركيزة.** $d = 700$: $C_1 = 700/\\sqrt{526.1\\times10^6/(25\\times300)} = 2.64 < C_{1,min} = 2.83$ — قليل على $L/12$. اعمل فيونكة: $1.2t = 0.90$ م فوق العمود الوسطاني، و $0.8t = 0.60$ م في البحور، والفيونكات طولها 1.2 م. الفيونكة بتجذب عزم — والمعمل بيدّي 607.5 kN·m عند الركيزة و 266.2 في البحور. وبـ $d = 850$: $C_1 = 2.99$، و $J = 0.742$، و $A_s = 2409$ مم² ← 5Ø25 (2454 مم²)."}]},{t:"quiz",q:{kind:"num",q:{en:"In the example, the moment for the columns and the top steel over the edge columns (kN·m)?",ar:"في المثال، العزم للأعمدة والحديد العلوي فوق الأعمدة الطرفية (kN·m)؟"},answer:175.4,tol:.003,unit:"kN·m",explain:{en:"$wL^2/24 = 51.97\\times81/24 = 175.4$ kN·m.",ar:"$wL^2/24 = 51.97\\times81/24 = 175.4$ kN·m."}}}]},{id:"apply",title:{en:"Your building: a girder instead of column B2?",ar:"مبناك: كمرة بدل العمود B2؟"},blocks:[{t:"p",text:{en:"The grid episode removed the ground-floor column B2 and let the beams on axes 2 and B share its load as a grid. Try a girder instead: the first-floor beam on axis 2 becomes a simple 9 m girder from A2 to C2 that carries its own slab strips, the upper column B2 ($P_{B2} = 246.1$ kN service) and the axis-B beam now resting on it ($R_B = 121.1$ kN): $P = 1.5\\times367.1 = 550.7$ kN at 5 m from A2. The roof-girder rule $t = L/10 = 0.9$ m gives $C_1 = 1.87$ — far too shallow. Sized as a transfer girder, 400 mm wide with $d = 3.5\\sqrt{M_U/(f_{cu}b)}$: $M_U = 1681$ kN·m → **400 × 1550**, $A_s = 3702$ mm² (8Ø25); the columns A2 and C2 get 456.8 and 505.9 kN and a design moment $M/3 = 560.5$ kN·m.",ar:"حلقة الجريد شالت عمود الدور الأرضي B2 وخلّت كمرات المحورين 2 و B يقسموا حمله كجريد. جرّب كمرة بدل كده: كمرة الدور الأول على المحور 2 بتبقى كمرة بسيطة 9 م من A2 لـ C2 شايلة شرايح بلاطتها، والعمود العلوي B2 ($P_{B2} = 246.1$ kN تشغيل) وكمرة المحور B اللي بقت راكبة عليها ($R_B = 121.1$ kN): $P = 1.5\\times367.1 = 550.7$ kN على بعد 5 م من A2. قاعدة كمرات الأسقف $t = L/10 = 0.9$ م بتدّي $C_1 = 1.87$ — قليل جداً. ولو صممناها ككمرة شايلة عمود، عرضها 400 مم و $d = 3.5\\sqrt{M_U/(f_{cu}b)}$: $M_U = 1681$ kN·m ← **400 × 1550**، و $A_s = 3702$ مم² (8Ø25)؛ والعمودين A2 و C2 بياخدوا 456.8 و 505.9 kN وعزم تصميم $M/3 = 560.5$ kN·m."}},{t:"p",text:{en:"A 1.55 m girder under a 3.20 m floor leaves **1.65 m** of headroom — useless. The grid carries the same post on two 300 × 800 beams and keeps 2.40 m. The depth rules of this episode belong to girders that carry their own roof; a girder that picks up a column is a transfer girder, and here the grid wins. Click column B2 or beam B1-2.",ar:"كمرة 1.55 م تحت دور 3.20 م بتسيب **1.65 م** بس ارتفاع صافي — مالهاش لازمة. والجريد بيشيل نفس العمود على كمرتين 300 × 800 وبيسيب 2.40 م. قواعد العمق في الحلقة دي للكمرات اللي شايلة سقفها؛ والكمرة اللي بتشيل عمود كمرة تحويل، وهنا الجريد هو اللي بيكسب. اضغط على العمود B2 أو الكمرة B1-2."}},{t:"widget",w:"building",props:{focus:"C0-B2",tags:["footings","cols-g","beams-1","slab-1","cols-1","beams-2","slab-2","grid-option","sys-girder"]}},{t:"quiz",q:{kind:"num",q:{en:"Clear height under the 1.55 m transfer girder, the first floor being at +3.20 m (m)?",ar:"الارتفاع الصافي تحت كمرة التحويل 1.55 م، والدور الأول على منسوب +3.20 م (م)؟"},answer:1.65,tol:.003,unit:"m",explain:{en:"$3.20 - 1.55 = 1.65$ m, against $3.20 - 0.80 = 2.40$ m under the grid beams.",ar:"$3.20 - 1.55 = 1.65$ م، قصاد $3.20 - 0.80 = 2.40$ م تحت كمرات الجريد."}}}]}],quiz:[{kind:"mcq",q:{en:"A 900 mm girder on 400 mm columns. The joint is designed as…",ar:"كمرة 900 مم على أعمدة 400 مم. الوصلة بتتصمم كـ…"},options:[{en:"a hinge (t_c ≤ t_G/2)",ar:"مفصلة (t_c ≤ t_G/2)"},{en:"a rigid joint",ar:"عقدة جاسئة"},{en:"a fixed support of the girder",ar:"ركيزة ثابتة للكمرة"}],answer:0,explain:{en:"$400 \\le 900/2 = 450$: the column acts as a hinge; it still gets wL²/24 in design.",ar:"$400 \\le 900/2 = 450$: العمود بيشتغل مفصلة؛ وبرضه بياخد wL²/24 في التصميم."}},{kind:"num",q:{en:"A simple girder spanning 11 m. Depth by the rule (m)?",ar:"كمرة بسيطة بحرها 11 م. العمق بالقاعدة (م)؟"},answer:1.1,tol:.003,unit:"m",explain:{en:"$L/10 = 1.1$ m.",ar:"$L/10 = 1.1$ م."}},{kind:"num",q:{en:"A cantilever girder of 3 m. Root depth by the rule (m)?",ar:"كمرة كابولي 3 م. عمق الجذر بالقاعدة (م)؟"},answer:.6,tol:.003,unit:"m",explain:{en:"$L_c/5 = 0.6$ m.",ar:"$L_c/5 = 0.6$ م."}},{kind:"num",q:{en:"Girders 7 m apart. Their width by the rule (m)?",ar:"كمرات بينها 7 م. عرضها بالقاعدة (م)؟"},answer:.35,tol:.003,unit:"m",explain:{en:"$\\max(0.30,\\ 7/20 = 0.35) = 0.35$ m.",ar:"$\\max(0.30,\\ 7/20 = 0.35) = 0.35$ م."}},{kind:"num",q:{en:"Girder w = 45 kN/m on 10 m, columns treated as hinges. Design moment of a column (kN·m)?",ar:"كمرة w = 45 kN/m على 10 م، والأعمدة معتبرة مفصلات. عزم تصميم العمود (kN·m)؟"},answer:187.5,tol:.003,unit:"kN·m",explain:{en:"$wL^2/24 = 45\\times100/24 = 187.5$ kN·m.",ar:"$wL^2/24 = 45\\times100/24 = 187.5$ kN·m."}},{kind:"tf",q:{en:"A continuous girder with intermediate hinges near L/5 suits weak soil.",ar:"الكمرة المستمرة بمفصلات وسطية قريب من L/5 مناسبة للتربة الضعيفة."},answer:!0,explain:{en:"The hinges make it determinate: a settling column only turns its parts.",ar:"المفصلات بتخليها محددة: العمود اللي بيهبط بيلف أجزاءها بس."}},{kind:"mcq",q:{en:"Why does a 25 m girder on neoprene bearings use an I-section?",ar:"ليه كمرة 25 م على ركائز نيوبرين بتاخد قطاع I؟"},options:[{en:"to save own weight on a long span",ar:"علشان توفّر الوزن الذاتي على بحر طويل"},{en:"because the bearings need a flange",ar:"لأن الركائز محتاجة شفة"},{en:"to make it continuous",ar:"علشان تبقى مستمرة"}],answer:0,explain:{en:"Above 20 m the own weight dominates; the I-section removes concrete from the web.",ar:"فوق 20 م الوزن الذاتي هو اللي بيحكم؛ وقطاع I بيشيل خرسانة من العصب."}},{kind:"num",q:{en:"A haunched girder with t = 0.9 m. Depth in the span (m)?",ar:"كمرة بفيونكة و t = 0.9 م. العمق في البحر (م)؟"},answer:.72,tol:.003,unit:"m",explain:{en:"$0.8t = 0.72$ m (and $1.2t = 1.08$ m over the supports).",ar:"$0.8t = 0.72$ م (و $1.2t = 1.08$ م فوق الركائز)."}}]};export{d as default};
